/**
 * galois.ts - GF(2^8) arithmetic, the field QR Code error correction lives in.
 *
 * ISO/IEC 18004 specifies Reed-Solomon error correction over the Galois field
 * GF(2^8) generated by the primitive polynomial
 *
 *     x^8 + x^4 + x^3 + x^2 + 1   ==   0b1_0001_1101   ==   0x11D
 *
 * Multiplication in this field is not integer multiplication; it is
 * "carry-less" polynomial multiplication modulo 0x11D. Since the field is
 * small, we precompute:
 *
 *   EXP[i] = alpha^i          (alpha = 2)  for i in [0, 255), extended to 510 so
 *                                          that EXP[a+b] works without a modulo
 *   LOG[x] = i such that alpha^i == x     (LOG[0] is undefined - 0 has no log)
 *
 * With those two tables, multiply/log are O(1) lookups instead of 8 shift-xor
 * rounds. This is the classic "log/antilog table" optimisation and is worth
 * roughly 8x on the Reed-Solomon inner loop.
 */

/** alpha^i (antilog table). Length 512 so EXP[a + b] is valid for a,b < 255. */
export const EXP = new Uint8Array(512);

/** Discrete logarithm table: LOG[EXP[i]] === i. LOG[0] is never read. */
export const LOG = new Uint8Array(256);

(function initTables(): void {
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d; // reduce modulo the primitive polynomial
  }
  // Mirror the cycle so that EXP[i] for i in [255, 511) is EXP[i - 255].
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
})();

/** Multiply two field elements. */
export function gfMul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0;
  return EXP[LOG[a] + LOG[b]];
}

/** Multiplicative inverse: gfMul(a, gfInv(a)) === 1. Throws for 0. */
export function gfInv(a: number): number {
  if (a === 0) throw new RangeError('0 has no multiplicative inverse in GF(2^8)');
  return EXP[255 - LOG[a]];
}

/** alpha^n for n >= 0, reduced into the field's cycle. */
export function gfPow(a: number, n: number): number {
  if (a === 0) return n === 0 ? 1 : 0;
  if (n < 0) return gfInv(gfPow(a, -n));
  const log = LOG[a];
  return EXP[(log * n) % 255];
}

/** Evaluate the polynomial at x (Horner's method). coeffs[0] is the highest power. */
export function gfPolyEval(coeffs: Uint8Array, x: number): number {
  let y = 0;
  for (let i = 0; i < coeffs.length; i++) y = gfMul(y, x) ^ coeffs[i];
  return y;
}

/** Multiply two polynomials whose coefficients are stored highest-power first. */
export function gfPolyMul(a: Uint8Array, b: Uint8Array): Uint8Array {
  const out = new Uint8Array(a.length + b.length - 1);
  for (let i = 0; i < a.length; i++) {
    if (a[i] === 0) continue;
    const logA = LOG[a[i]];
    for (let j = 0; j < b.length; j++) {
      if (b[j] === 0) continue;
      out[i + j] ^= EXP[logA + LOG[b[j]]];
    }
  }
  return out;
}
